import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse(`{"title":"Page 15 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"15","title":"Page 15 | Home","prev":"/page/14/","next":"/page/16/","posts":[{"title":"Vue实现双Slider","url":"/posts/2020-06-14-vue-dual-slider/","date":"2020-06-14 21:31","tags":["frontend","vue"],"html":"<p>前端由于历史原因，基本上没有组件的概念，原生的 HTML 元素提供的功能非常简陋，所以都需要开发者自己实现或者定制组件。这次讲讲双 Slider 的实现。</p>\\n<h2 id=\\"技术选型\\" tabindex=\\"-1\\">技术选型 <a class=\\"header-anchor\\" href=\\"#技术选型\\" aria-label=\\"Permalink to &quot;技术选型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前比较流行的 Vue 的组件库是<a href=\\"https://element.eleme.io/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Element</a> 和 <a href=\\"https://www.iviewui.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">View UI</a>。这两个组件库都使用了最常用的方法，使用<code>div</code>或者<code>span</code>，元素模拟滑动条，监听事件，并处理滑动。但是 HTML 元素本身提供了<a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTML/Element/input/range\\" target=\\"_blank\\" rel=\\"noreferrer\\">Range</a>标签，我们可以修改下样式来使用，这样就避免自己直接处理事件监听，也可以减少浏览器兼容性问题。</p>\\n<h2 id=\\"样式定制化\\" tabindex=\\"-1\\">样式定制化 <a class=\\"header-anchor\\" href=\\"#样式定制化\\" aria-label=\\"Permalink to &quot;样式定制化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前针对 Range 元素的样式定制化还没有纳入 Web 标准，所以在处理起来稍微花点功夫。首先，我们需要修改默认的滑块样式。使用的 CSS 选择器是<a href=\\"https://developer.mozilla.org/en-US/docs/Web/CSS/::-webkit-slider-thumb\\" target=\\"_blank\\" rel=\\"noreferrer\\">-webkit-slider-thumb</a>。由于未纳入标准，需要使用浏览器前缀才行。这里我们可以借助 <a href=\\"https://github.com/jonathantneal/postcss-input-range\\" target=\\"_blank\\" rel=\\"noreferrer\\">postcss-input-range</a> 插件来完成这项工作。</p>\\n<h2 id=\\"双-slider-实现\\" tabindex=\\"-1\\">双 Slider 实现 <a class=\\"header-anchor\\" href=\\"#双-slider-实现\\" aria-label=\\"Permalink to &quot;双 Slider 实现&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>HTML 本身只提供了单滑块，要想实现双 Slider，只能两个叠加在一起了，并且需要自己实现 Slider 的选中范围，因为目前的 css selector 并不能达到这种效果。如何动态的控制 Slider 的显示长度呢？当然可以计算出目前的选中百分比，通过 css variables 来达到更新样式的效果。</p>\\n<h2 id=\\"slider-滑动规则\\" tabindex=\\"-1\\">Slider 滑动规则 <a class=\\"header-anchor\\" href=\\"#slider-滑动规则\\" aria-label=\\"Permalink to &quot;Slider 滑动规则&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当然，我们左边的滑块不能滑过右边的滑块，这是基本常识。这里就需要监听<code>input</code> 事件，当超出范围的时候，强制把值重置回合法值就可以了。</p>\\n<h2 id=\\"实现效果\\" tabindex=\\"-1\\">实现效果 <a class=\\"header-anchor\\" href=\\"#实现效果\\" aria-label=\\"Permalink to &quot;实现效果&quot;\\">&ZeroWidthSpace;</a></h2>\\n<iframe height=\\"325\\" style=\\"width: 100%;\\" scrolling=\\"no\\" title=\\"Slider\\" src=\\"https://codepen.io/acgotaku/embed/preview/LYGZQva?height=325&theme-id=dark&default-tab=js,result\\" frameborder=\\"no\\" allowtransparency=\\"true\\" allowfullscreen=\\"true\\">\\n  See the Pen <a href='https://codepen.io/acgotaku/pen/LYGZQva'>Slider</a> by 雪月秋水\\n  (<a href='https://codepen.io/acgotaku'>@acgotaku</a>) on <a href='https://codepen.io'>CodePen</a>.\\n</iframe>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>能用原生 HTML 标签来解决的问题，尽量还是不要自己实现事件监听了。这样性能也会更好，兼容性上也不会太差。</p>\\n"},{"title":"React的TypeScript写法","url":"/posts/2020-05-22-react-typescript/","date":"2020-05-22 22:43","tags":["frontend","react"],"html":"<p>最近在用 React 写前端，不得不说 React 对 TypeScript 的支持比 Vue 好，Vue 的话，在组件传 Prop 的时候会丢失静态检查。</p>\\n<h2 id=\\"react-组件写法\\" tabindex=\\"-1\\">React 组件写法 <a class=\\"header-anchor\\" href=\\"#react-组件写法\\" aria-label=\\"Permalink to &quot;React 组件写法&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前 React 有两种写法，一种是 Class Components，另外一种是 Function Components。这两种写法都可以，不过如何选择呢？ 个人倾向于复杂的组件需要管理生命周期或者事件响应的话使用 Class Components，简单的组件例如只是展示一个按钮或者链接。使用 Function Components。 因为 Function Components 写起来代码更短。</p>\\n<h2 id=\\"class-components\\" tabindex=\\"-1\\">Class Components <a class=\\"header-anchor\\" href=\\"#class-components\\" aria-label=\\"Permalink to &quot;Class Components&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> React, { ReactNode } </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> 'react'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">interface</span><span style=\\"color:#6F42C1\\"> ButtonProps</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  disabled</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  children</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> ReactNode</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">interface</span><span style=\\"color:#6F42C1\\"> ButtonStates</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  count</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">class</span><span style=\\"color:#6F42C1\\"> Button</span><span style=\\"color:#D73A49\\"> extends</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">Component</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">ButtonProps</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#6F42C1\\">ButtonStates</span><span style=\\"color:#24292E\\">> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  static</span><span style=\\"color:#E36209\\"> defaultProps</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    disabled: </span><span style=\\"color:#005CC5\\">false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  constructor</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">props</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> ButtonProps</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    super</span><span style=\\"color:#24292E\\">(props);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.state </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      count: </span><span style=\\"color:#005CC5\\">0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  render</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#24292E\\"> { </span><span style=\\"color:#005CC5\\">disabled</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">children</span><span style=\\"color:#24292E\\"> } </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> this</span><span style=\\"color:#24292E\\">.props;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> &#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> disabled</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{disabled}>{children}&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">>;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> default</span><span style=\\"color:#24292E\\"> Button;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br></div></div><p>上面的例子演示了如何定义属性和状态，并且设置默认属性值和初始化状态。</p>\\n<h2 id=\\"function-components\\" tabindex=\\"-1\\">Function Components <a class=\\"header-anchor\\" href=\\"#function-components\\" aria-label=\\"Permalink to &quot;Function Components&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> React, { ReactNode } </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> 'react'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">interface</span><span style=\\"color:#6F42C1\\"> ButtonProps</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  disabled</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  children</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> ReactNode</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> Button</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">ButtonProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({ </span><span style=\\"color:#E36209\\">disabled</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">children</span><span style=\\"color:#24292E\\"> }) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> &#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> disabled</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{disabled}>{children}&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">>;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> default</span><span style=\\"color:#24292E\\"> Button;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><p>Function Components 不能直接传入 state 参数，需要使用 <code>useState</code> 函数来处理。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>React 写起来非常方便，但是条件渲染还是没有 Vue 方便。由于没有官方的 TypsScript 例子。只能自己总结一下方便以后使用了。</p>\\n"},{"title":"Vue表单组件如何自动化输入","url":"/posts/2020-04-23-vue-hack-form/","date":"2020-04-23 22:43","tags":["frontend","vue"],"html":"<p>使用 Vue 的数据双向绑定功能可以很方便的完成表单的数据收集和提交，再也不用自己手动监听事件和收集数据了。但同时自动化输入也变得复杂起来。</p>\\n<h2 id=\\"传统表单自动化输入\\" tabindex=\\"-1\\">传统表单自动化输入 <a class=\\"header-anchor\\" href=\\"#传统表单自动化输入\\" aria-label=\\"Permalink to &quot;传统表单自动化输入&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>对于传统的表单我们可以很简单的自动化输入过程，例如<code>checkbox</code>和<code>input</code>元素，我们可以自动选中和输入内容：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">document.</span><span style=\\"color:#6F42C1\\">querySelector</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'.checkbox'</span><span style=\\"color:#24292E\\">).checked </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">document.</span><span style=\\"color:#6F42C1\\">querySelector</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'.input'</span><span style=\\"color:#24292E\\">).value </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>当用户提交的时候，程序会读取相应元素的值，然后填充到请求里。</p>\\n<h2 id=\\"vue-组件自动化输入\\" tabindex=\\"-1\\">Vue 组件自动化输入 <a class=\\"header-anchor\\" href=\\"#vue-组件自动化输入\\" aria-label=\\"Permalink to &quot;Vue 组件自动化输入&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这里我们以现在流行的<a href=\\"https://element.eleme.io/#/en-US\\" target=\\"_blank\\" rel=\\"noreferrer\\">Element</a>为例子演示如何自动化输入。用过 Vue 的人都知道， <code>v-model</code>是用来进行双向绑定的。它的原理是：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">Vue.</span><span style=\\"color:#6F42C1\\">component</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'custom-input'</span><span style=\\"color:#24292E\\">, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  props: [</span><span style=\\"color:#032F62\\">'value'</span><span style=\\"color:#24292E\\">],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  template: </span><span style=\\"color:#032F62\\">\`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    &#x3C;input</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">      v-bind:value=\\"value\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">      v-on:input=\\"$emit('input', $event.target.value)\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  \`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>到这里，我们就知道了通过<code>$emit('input', value)</code>的方式，可以绑定想要输入的值，直接使用传统方式修改<code>input</code>元素的值，有时候不会触发<code>input</code>事件，所以不是一个可行的办法。</p>\\n<p>接下来，我们讲下如何选中元素并调用<code>$emit</code>，例子是 Vue 官网的<a href=\\"https://element.eleme.io/#/en-US/component/input\\" target=\\"_blank\\" rel=\\"noreferrer\\">搜索框</a></p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> input</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> document.</span><span style=\\"color:#6F42C1\\">querySelector</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'.el-input'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">input.__vue__.</span><span style=\\"color:#6F42C1\\">$emit</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'input'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'Hello world'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>在<code>console</code>里输入这两行代码，你会发现搜索框里被填入了<code>Hello World</code>。Vue 实例被隐藏到了 DOM 中，只要知道如何访问 Vue 然好调用<code>$emit</code>，问题就迎刃而解。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在的前端框架用起来方便，但也隐藏了大量细节。导致做自动化的时候不知道如何下手，尝试修改元素的值，但发现提交的时候还是没有带上正确的数值。这时候就需要思考框架绑定数据的本质是什么，\\n弄清了本质，其实做起来发现更简单！</p>\\n"}]},"relativePath":"page/15/index.md","filePath":"page/[page].md"}`),e={name:"page/15/index.md"};function l(p,o,r,t,c,i){return n(),a("div")}const b=s(e,[["render",l]]);export{u as __pageData,b as default};
